 * subscription's); when given it replaces whatever plan was recorded before,
 * so a plan change resizes the bucket on the very next request.
 */
export async function consumeRateLimit(
  orgId: OrgId,
  bucketKey: string,
  cost = 1,
  plan?: PlanId | null,
): Promise<RateLimitVerdict> {
  if (plan) setOrgPlan(orgId, plan);

  const config = configFor(orgId, bucketKey);
  const key = `${orgId}:${bucketKey}`;
  const nowMs = Date.now();

  const state = buckets.get(key) ?? {
    tokens: config.capacity,
    capacity: config.capacity,
    updatedAt: nowMs,
  };
  // When the plan moved the ceiling since the last request, what was already
  // spent carries over rather than the raw token count: an upgrade gains the
  // extra headroom at once, a downgrade does not refund the difference.
  const spent = Math.max(0, state.capacity - state.tokens);
  const elapsedMinutes = (nowMs - state.updatedAt) / 60_000;
  const tokens = Math.min(
    config.capacity,
    Math.max(0, config.capacity - spent) +
      elapsedMinutes * config.refillPerMinute,
  );

  const allowed = tokens >= cost;
  const remaining = allowed ? tokens - cost : tokens;
  buckets.set(key, {
    tokens: remaining,
    capacity: config.capacity,
    updatedAt: nowMs,
  });
'''
