import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";
vi.mock("@/lib/logger", async () => (await import("$R/tests/server/_support/doubles/misc")).loggerModule);

import * as orgRepo from "@/server/repositories/organization-repository";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import * as billingService from "@/server/services/billing-service";
import * as projectService from "@/server/services/project-service";
import * as invitationService from "@/server/services/invitation-service";
import * as commentService from "@/server/services/comment-service";
import * as issueService from "@/server/services/issue-service";
import * as webhookService from "@/server/services/webhook-service";
import { runTrialExpiryJob } from "@/server/jobs/trial-expiry-job";
import { getDb, subscriptions } from "@/server/db";
import { eq } from "drizzle-orm";
import { createTenant, issueInput, useTemporaryDatabase } from "$R/tests/server/_support/fixtures";

let cleanup: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); });
afterAll(() => cleanup());

const proj = (orgId: any, n: number) => ({ orgId, name: "Project " + n, slug: "p" + n, key: "P" + n, description: null, visibility: "org" as const, leadId: null, color: "#6366f1", targetDate: null });

describe("plan authority", () => {
  it("upgrade free->growth takes effect everywhere", async () => {
    const t = await createTenant("up", "free");
    const other = await createTenant("other", "free");
    await billingService.changePlan(t.actors.owner, { orgId: t.org.id, plan: "growth", interval: "monthly" });
    expect((await orgRepo.findOrgById(t.org.id))!.plan).toBe("growth");
    expect((await orgRepo.findOrgBySlug("up"))!.plan).toBe("growth");
    expect((await orgRepo.listOrgsForUser(t.userIds.owner)).map(o => o.plan)).toEqual(["growth"]);
    expect((await orgRepo.findOrgById(other.org.id))!.plan).toBe("free");
    await projectService.createProject(t.actors.owner, proj(t.org.id, 2));
    await projectService.createProject(t.actors.owner, proj(t.org.id, 3));
    await invitationService.inviteMembers(t.actors.owner, { orgId: t.org.id, invites: [{ email: "x@y.z", role: "member" }] });
    const issue = await issueService.createIssue(t.actors.member, issueInput(t.org.id, t.project.id));
    for (let i = 0; i < 80; i++) {
      await commentService.createComment(t.actors.member, { orgId: t.org.id, issueId: issue.id, body: "hi " + i, parentId: null, mentionedUserIds: [] });
    }
    const oissue = await issueService.createIssue(other.actors.member, issueInput(other.org.id, other.project.id));
    let refused = 0;
    for (let i = 0; i < 70; i++) {
      try { await commentService.createComment(other.actors.member, { orgId: other.org.id, issueId: oissue.id, body: "hi " + i, parentId: null, mentionedUserIds: [] }); } catch { refused++; }
    }
    expect(refused).toBeGreaterThan(0);
    await expect(projectService.createProject(other.actors.owner, proj(other.org.id, 2))).resolves.toBeTruthy();
    await expect(projectService.createProject(other.actors.owner, proj(other.org.id, 3))).rejects.toThrow();
  });

  it("disagreeing records follow the subscription without a new change", async () => {
    const t = await createTenant("stale", "free");
    await subscriptionRepo.updateSubscriptionPlan(t.org.id, "growth", "monthly");
    expect((await orgRepo.findOrgById(t.org.id))!.plan).toBe("growth");
    await projectService.createProject(t.actors.owner, proj(t.org.id, 2));
    await projectService.createProject(t.actors.owner, proj(t.org.id, 3));
  });

  it("downgrade to starter refuses webhooks", async () => {
    const t = await createTenant("down", "growth");
    await billingService.changePlan(t.actors.owner, { orgId: t.org.id, plan: "starter", interval: "monthly" });
    await expect(webhookService.createWebhook(t.actors.admin, { orgId: t.org.id, url: "https://e.x/h", eventTypes: ["billing.plan_changed"] })).rejects.toThrow(/not included/);
  });

  it("trial sweep", async () => {
    const chose = await createTenant("chose", "growth");
    const lapsed = await createTenant("lapsed", "growth");
    await billingService.changePlan(chose.actors.owner, { orgId: chose.org.id, plan: "starter", interval: "monthly" });
    const later = new Date(Date.now() + 30 * 86400000);
    const r1 = await runTrialExpiryJob(later);
    expect((await orgRepo.findOrgById(chose.org.id))!.plan).toBe("starter");
    expect((await orgRepo.findOrgById(lapsed.org.id))!.plan).toBe("free");
    const row = getDb().select().from(subscriptions).where(eq(subscriptions.orgId, lapsed.org.id)).get();
    expect(row!.plan).toBe("free");
    await expect(projectService.createProject(lapsed.actors.owner, proj(lapsed.org.id, 2))).resolves.toBeTruthy();
    await expect(projectService.createProject(lapsed.actors.owner, proj(lapsed.org.id, 3))).rejects.toThrow();
    const r2 = await runTrialExpiryJob(later);
    console.log(JSON.stringify(r1), JSON.stringify(r2));
  });
});
EOF
